import heapq

def toposort(nodes, edges):
    adj = {node: set() for node in nodes}
    in_degree = {node: 0 for node in nodes}

    for u, v in edges:
        if v not in adj[u]:
            adj[u].add(v)
            in_degree[v] += 1

    queue = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(queue)

    result = []
    while queue:
        u = heapq.heappop(queue)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(queue, v)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected in graph")

    return result

def stable_batches(items, limit):
    if not items:
        return []

    if limit <= 0:
        raise ValueError("Limit must be positive.")

    batches = []
    current_batch = []
    current_sum = 0

    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("Weight must be positive and not exceed limit.")

        if current_sum + weight <= limit:
            current_batch.append(name)
            current_sum += weight
        else:
            batches.append(current_batch)
            current_batch = [name]
            current_sum = weight

    if current_batch:
        batches.append(current_batch)

    return batches
